package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealMatrix constructor.
 */
public class OpenMapRealMatrix_OpenMapRealMatrix_TriageGen0Test {









    @Test
    public void testConstructorWithValues() {
        int rows = 2;
        int cols = 2;
        OpenMapRealMatrix matrix = new OpenMapRealMatrix(rows, cols);

        // Verify initial entries are 0.0
        matrix.setEntry(0, 0, 1.5);
        matrix.setEntry(1, 1, 2.5);

        assertEquals(1.5, matrix.getEntry(0, 0), 1e-10);
        assertEquals(2.5, matrix.getEntry(1, 1), 1e-10);
        assertEquals(0.0, matrix.getEntry(0, 1), 1e-10);
        assertEquals(0.0, matrix.getEntry(1, 0), 1e-10);
    }


}

package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealMatrix constructor.
 */
public class OpenMapRealMatrix_OpenMapRealMatrix_TriageGen0Test {











    @Test
    public void testCopyConstructor() {
        OpenMapRealMatrix original = new OpenMapRealMatrix(3, 3);
        original.setEntry(1, 1, 42.0);

        OpenMapRealMatrix copy = new OpenMapRealMatrix(original);

        assertNotNull(copy);
        assertEquals(original.getRowDimension(), copy.getRowDimension());
        assertEquals(original.getColumnDimension(), copy.getColumnDimension());
        assertEquals(original.getEntry(1, 1), copy.getEntry(1, 1), 1e-10);

        // Ensure it is a deep copy (modifying copy shouldn't affect original)
        copy.setEntry(1, 1, 0.0);
        assertNotEquals(original.getEntry(1, 1), copy.getEntry(1, 1));
    }
}
